import { BranchingStory } from "march/landing"

// gizemli kapılar: üç kapıdan birini seç; her adımda kaç adım attığını sayar
export function MysteryDoor() {
  let $steps = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <BranchingStory start="hol" minHeight="14rem" label="Gizemli kapılar" onChange={(p: string[]) => $steps = p.length - 1}
      passages={{
        hol: { title: "🚪🚪🚪 Üç kapı", body: "Uzun bir koridordasın. Önünde üç kapı var.", choices: [
          { label: "Kırmızı kapı", to: "kirmizi" }, { label: "Mavi kapı", to: "mavi" }, { label: "Minicik kapı", to: "mini", note: "eğilmen gerek" }] },
        kirmizi: { title: "🔥 Sıcak oda", body: "İçerisi fırın gibi. Ortada bir dondurma makinesi duruyor.", choices: [
          { label: "Dondurma al", to: "dondurma" }, { label: "Geri çık", to: "hol" }] },
        mavi: { title: "🌊 Akvaryum", body: "Duvarlar camdan, bir ahtapot sana el sallıyor.", ending: "Ahtapotun arkadaşı" },
        mini: { title: "🐭 Fare kasabası", body: "Küçülüyorsun! Fareler seni çay içmeye davet ediyor.", ending: "Kasabanın konuğu" },
        dondurma: { title: "🍦 Serinlik", body: "Fıstıklı ve limonlu. Fırın artık umrunda değil.", ending: "Dondurmacı" },
      }} />
    <small sx={{ color: "muted" }}>{$steps} adım attın</small>
  </div>
}

import { BranchingStory } from "march/landing"
import { Button, toast } from "march/ui"
import { coffee } from "march/icons"

// bir kahve markasının sitesinde "hangi çekirdek sana göre?" testi: her son bir ürüne çıkar
export function CoffeeQuiz() {
  return <BranchingStory start="sabah" label="Kahve testi" transition="slide" minHeight="16rem"
    labels={{ start: "Başla", restart: "Testi yeniden çöz", endingPrefix: "Sana göre: ", endings: (n: number, total: number) => `${total} çekirdekten ${n} tanesini keşfettin` }}
    action={<Button icon={coffee} on:click={() => toast("Sepete eklendi")}>Sepete ekle</Button>}
    passages={{
      sabah: { title: "Kahveni nasıl içersin?", body: "Önce alışkanlığını öğrenelim.", choices: [
        { label: "Sade, filtre", note: "bol bardak", to: "filtre" }, { label: "Sütlü", note: "latte, flat white", to: "sutlu" }] },
      filtre: { title: "Hangi tat?", body: "Filtre kahvede tat notaları belirgin olur.", choices: [
        { label: "Meyvemsi, asidik", to: "etiyopya" }, { label: "Çikolatalı, yumuşak", to: "brezilya" }] },
      sutlu: { title: "Ne kadar sert?", body: "Süt bazı çekirdeklerin tadını örter.", choices: [
        { label: "Sert olsun", to: "sumatra" }, { label: "Dengeli", to: "brezilya" }] },
      etiyopya: { title: "Etiyopya Yirgacheffe", ending: "Etiyopya", color: "brand-orange", body: "Yasemin ve limon notaları. 250 g · 340 ₺" },
      brezilya: { title: "Brezilya Santos", ending: "Brezilya", color: "brand-gold", body: "Kakao ve fındık. 250 g · 290 ₺" },
      sumatra: { title: "Sumatra Mandheling", ending: "Sumatra", color: "brand-purple", body: "Toprak ve baharat, gövdeli. 250 g · 320 ₺" },
    }} />
}

import { BranchingStory, type StoryChoice } from "march/landing"
import { Segmented, Toggle, Button, Card } from "march/ui"

// BranchingStory'nin bütün özellikleri bir arada: pasajlar, ilk pasaj, dışarıdan yönetilen yol (path) ve onChange,
// iz, bulunan sonlar, sondaki eylem, en küçük yükseklik, erişilebilir ad, bütün metinler (labels), yeniden başlat
// düğmesi, rakam tuşları, kendi seçenek çizimin, sayfa geçişi (hazır ya da kendi hareketin) ve sınıf
const PASSAGES = {
  orman: { title: "Ormanın girişi", color: "brand-green" as const, media: <span sx={{ text: "2xl" }}>🌲</span>, body: "İki patika var.", choices: [
    { label: "Dere boyu", note: "serin", to: "dere" }, { label: "Tepeye", note: "dik", to: "tepe" }] },
  dere: { title: "Derenin kıyısı", body: "Bir sal bağlı duruyor.", choices: [{ label: "Sala bin", to: "sal" }, { label: "Yürümeye devam", to: "tepe" }] },
  tepe: { title: "Tepede", ending: "Manzara", body: "Bütün vadi ayaklarının altında." },
  sal: { title: "Sal yolculuğu", ending: "Kaptan", body: "Dere seni göle taşıdı." },
}
// kendi geçişin: eski pasaj solar, yenisi yandan gelir
const OWN = (side: 1 | -1) => ({ leave: { opacity: [1, 0] }, enter: { opacity: [0, 1], transform: [`translateX(${40 * side}px)`, "translateX(0px)"] }, duration: 400 })

export function BranchingStoryLab() {
  let $path = ["orman"]
  let $move: "yok" | "kendi" = "yok"
  let $trail = true
  let $keys = true
  let $own = false
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Geçiş" options={["yok", "kendi"]} bind:value={$move} />
        <Toggle label="İz" bind:value={$trail} />
        <Toggle label="Rakam tuşları" bind:value={$keys} />
        <Toggle label="Kendi seçeneklerim" bind:value={$own} />
        <Button variant="secondary" on:click={() => $path = ["orman"]}>Başa sar</Button>
      </div>
    </Card>
    {() => { const move = $move, trail = $trail, keys = $keys, own = $own; return <BranchingStory class="lab-bs"
      passages={PASSAGES} start="orman" path={() => $path} onChange={(p: string[]) => $path = p}
      trail={trail} endings action={<Button variant="link" href="#rota">Rotayı indir</Button>} minHeight="12rem" label="Orman macerası"
      labels={{ path: "Yolun", start: "Giriş", endings: (n: number, total: number) => `${n}/${total} son`, missing: "Bu yol kayıp.", end: "Bitti", endingPrefix: "Son: ", restart: "Yeniden" }}
      restart keys={keys} transition={move === "yok" ? "none" : OWN}
      renderChoice={own ? (c: StoryChoice, i: number) => <span class="lab-choice">{`${i + 1}. `}<b>{c.label}</b></span> : undefined} /> }}
    <p sx={{ color: "muted" }} class="lab-path">Yol: {$path.join(" → ")}</p>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { BranchingStoryLab } from "./BranchingStoryLab.tsx"

// BranchingStoryLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ilk pasaj, ad ve numaralı seçenekler", () => {
  const s = renderTest(() => <BranchingStoryLab />)
  expect(s.get(".lab-bs")?.getAttribute("aria-label")).toBe("Orman macerası")
  expect(s.get(".lab-bs .m-bs-title")?.textContent).toBe("Ormanın girişi")
  expect(s.all(".lab-bs .m-bs-key").map((k: Element) => k.textContent)).toEqual(["1", "2"])
  expect(s.find("0/2 son")).not.toBe(null)
})

test("bir seçim yeni pasajı açar, onChange yolu yazar", async () => {
  const s = renderTest(() => <BranchingStoryLab />)
  await s.click("Dere boyu")
  expect(s.find("Derenin kıyısı")).not.toBe(null)
  expect(s.get(".lab-path")?.textContent).toBe("Yol: orman → dere")
})

test("sona varınca son adı, sayaç ve kendi düğme metni", async () => {
  const s = renderTest(() => <BranchingStoryLab />)
  await s.click("Tepeye")
  expect(s.text()).toContain("Son: Manzara")
  expect(s.find("1/2 son")).not.toBe(null)
  await s.click("Yeniden")
  expect(s.get(".lab-path")?.textContent).toBe("Yol: orman")
})

test("rakam tuşu seçer; dışarıdan başa sarılır", async () => {
  const s = renderTest(() => <BranchingStoryLab />)
  await s.press("2", s.get(".lab-bs")!)
  expect(s.find("Tepede")).not.toBe(null)
  await s.click("Başa sar")
  expect(s.find("Ormanın girişi")).not.toBe(null)
})
